import {practicePage, mountPractice} from './practice.mjs';
import {guidePage, mountGuide} from './guides.mjs';
import * as math from './math.mjs';
const $=selector=>document.querySelector(selector);
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,size=17)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({path:'<path d="M4 4h6v7H4zM14 4h6v4h-6zM14 12h6v8h-6zM4 15h6v5H4z"/>',lab:'<path d="M9 3h6M10 3v7L4 19c-.5 1 .5 2 1.5 2h13c1 0 2-1 1.5-2l-6-9V3M7 15h10"/>',book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1v15"/>',note:'<path d="M5 3h14v18H5zM8 8h8M8 12h8M8 16h5"/>',arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>'})[name]||''}</svg>`;
const KEY='safeposttrain-learning-v1';
const fresh=()=>({version:1,completed:[],bookmarks:[],answers:{},notes:{},mistakes:{},last:'01'});
let state=fresh(),data,activeStage=-1,searchQuery='',toastTimer,storageAvailable=true;
const labs={
 gradient:{title:'一次 SFT 梯度更新',caption:'从 loss 到参数，再从参数回到概率。',chapter:'01',formula:'p = σ(θ)；∂L/∂θ = p − y；θ_new = θ − η(p − y)',note:'只有一个参数和两个动作的教学模型，目标 y 为 0 或 1。执行按钮实际更新这个教学参数，不调用或训练真实语言模型。'},
 gae:{title:'GAE：把反馈传回前面的步骤',caption:'沿三步轨迹，从最后一个奖励向前计算优势。',chapter:'08',formula:'δₜ = rₜ + γV(sₜ₊₁) − V(sₜ)；Aₜ = δₜ + γλAₜ₊₁',note:'只演示一段连续、无 padding、无中间 episode 边界的轨迹。环境真正终止时忽略末端价值；仅截断采样时使用末端价值 bootstrap。A+V 是本例的价值训练目标。'},
 temperature:{title:'温度与概率分布',caption:'同一组 logits，为什么会产生不同回答？',chapter:'01',formula:'pᵢ = exp(zᵢ/T) / Σⱼexp(zⱼ/T)',note:'固定四个教学 logits：[2, 1, 0, −1]。温度大于零；熵使用自然对数。改变温度只改变采样分布。'},
 sft:{title:'SFT 的 token 与 mask',caption:'点击监督位置，亲手改变 loss 的分子与分母。',chapter:'04',formula:'L = −Σₜmₜ log(pₜ) / Σₜmₜ',note:'教学概率不来自真实模型。用户 token 即使不计 loss，仍可作为上下文。全部取消时，loss 无定义。'},
 lora:{title:'LoRA 参数计算器',caption:'从一个投影层，看懂低秩更新节省了什么。',chapter:'05',formula:'W′ = W + (α/r)BA；参数量 = r(d_in + d_out)',note:'仅计算单个线性层，不含 bias、其他层、激活或优化器状态。参数比例不是总显存比例。'},
 reward:{title:'奖励与偏好概率',caption:'奖励分差如何变成“更喜欢这个回答”的概率？',chapter:'06',formula:'P(chosen ≻ rejected) = σ(r_w − r_l)',note:'使用 Bradley–Terry 教学模型。共同平移两个分数不改变概率；绝对分值不是跨奖励模型的统一质量刻度。'},
 dpo:{title:'DPO 偏好实验',caption:'四个 log-prob 和一个 beta，把损失算清楚。',chapter:'07',formula:'z = β[(log πw − log πl) − (log πref,w − log πref,l)]；L = −log σ(z)',note:'输入为回答序列 log-prob 的和。此实验计算单样本目标，不执行梯度更新，也不代表真实模型训练结果。'},
 ppo:{title:'PPO 裁剪实验',caption:'优势符号改变时，裁剪的作用也会改变。',chapter:'08',formula:'J = min(ratio·A, clip(ratio,1−ε,1+ε)·A)；loss = −J',note:'绿色曲线是裁剪后的目标，淡紫色是未裁剪目标。这里只演示 policy surrogate，不包含价值损失、熵或 KL。'},
 grpo:{title:'GRPO 组内优势',caption:'观察同一组回答中，谁得到正向更新信号。',chapter:'09',formula:'Aᵢ = (rᵢ − mean(r)) / (std(r) + ε)',note:'使用总体标准差与 ε=1e−8。奖励不是实测数据；实际框架可能使用不同归一化方案。'},
 sampling:{title:'多采样的收益与假设',caption:'尝试更多次，至少一次成功的概率如何变化？',chapter:'11',formula:'P(至少一次成功) = 1 − (1 − p)ᴺ',note:'假设各次独立、同分布，且存在完美选择器。真实采样可能相关、评分器可能选错，图中的概率不能直接当成实际性能。'},
 safety:{title:'安全与误拒绝',caption:'把有害完成和合法请求误拒绝分开统计。',chapter:'12',formula:'有害完成率 = 有害回答数 / 有害请求数；误拒绝率 = 误拒数 / 合法请求数',note:'这些是两种独立切片的教学计数，不是同一个分类混淆矩阵。未拒绝的合法回答仍需检查质量；有害完成不等于简单的“不拒绝”。'},
 memory:{title:'训练显存拆解',caption:'权重之外，还有梯度、优化器和激活。',chapter:'14',formula:'示例静态状态 = 参数量 × (2 + 2 + 4 + 8) 字节',note:'假设 2B 权重、2B 梯度、4B 主副本、8B Adam 状态，所有静态状态理想均分。另加每卡激活估计；不含通信/临时峰值。GB 使用十进制。不是硬件可运行保证。'}
};
function validateState(raw){
 if(!raw||raw.version!==1||typeof raw!=='object'||Array.isArray(raw))throw Error('不支持的学习记录格式');
 const valid=new Set(data.course.map(c=>c.id)),out=fresh();
 for(const name of ['completed','bookmarks']){if(raw[name]!==undefined&&!Array.isArray(raw[name]))throw Error('学习记录列表格式错误');out[name]=[...new Set((raw[name]||[]).filter(x=>valid.has(x)))];}
 for(const name of ['notes','answers','mistakes']){if(raw[name]!==undefined&&(!raw[name]||typeof raw[name]!=='object'||Array.isArray(raw[name])))throw Error('学习记录字段格式错误');}
 for(const c of data.course){
  if(typeof raw.notes?.[c.id]==='string'){if(raw.notes[c.id].length>20000)throw Error('单章笔记超过 20000 字，请先拆分备份。');out.notes[c.id]=raw.notes[c.id];}
  if(Array.isArray(raw.answers?.[c.id]))out.answers[c.id]=c.quizzes.map((q,i)=>Number.isInteger(raw.answers[c.id][i])&&raw.answers[c.id][i]>=0&&raw.answers[c.id][i]<q.options.length?raw.answers[c.id][i]:null);
  if(Array.isArray(raw.mistakes?.[c.id]))out.mistakes[c.id]=[...new Set(raw.mistakes[c.id].filter(x=>Number.isInteger(x)&&x>=0&&x<c.quizzes.length))];
 }
 out.completed=out.completed.filter(id=>data.course.find(c=>c.id===id).quizzes.every((q,i)=>out.answers[id]?.[i]===q.correct));
 if(valid.has(raw.last))out.last=raw.last;return out;
}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageAvailable=true;}catch{if(storageAvailable)toast('浏览器未能保存记录，请导出备份。');storageAvailable=false;}}
function mergeNotes(a,b){if(!a||a===b)return b;const merged=a+'\n\n—— 导入笔记 ——\n'+b;if(merged.length>20000)throw Error('合并后的笔记超出 20000 字，未修改原记录。请先分别备份。');return merged;}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3600);}
const footer=()=>`<footer class="footer"><span>SafePostTrain Lab · 从理解原理到可靠实践</span><span>进度仅保存在当前浏览器 · 无需账号与 API Key</span></footer>`;
function route(){const raw=location.hash.replace(/^#\/?/,'').split('?')[0].split('/');return{view:raw[0]||'path',id:raw[1]};}
function navItem(view,label,name,count=''){return `<a class="nav-link ${route().view===view?'active':''}" href="#/${view}">${icon(name)}${label}${count?`<span class="count">${count}</span>`:''}</a>`;}
function shell(){
 const r=route();
 $('#app').innerHTML=`<aside class="sidebar" aria-label="课程导航"><button class="menu-close" data-action="close-menu" aria-label="关闭课程导航">×</button><a class="brand" href="#/path"><span class="brand-mark">s.</span><span class="brand-name">SafePostTrain<span>LEARNING LAB</span></span></a><nav class="nav-primary">${navItem('path','学习路径','path')}${navItem('guide','学习指南','book')}${navItem('labs','交互实验','lab',Object.keys(labs).length)}${navItem('practice','GPU 训练','lab')}${navItem('glossary','术语速查','book')}${navItem('review','我的学习','note')}</nav><div class="nav-label">COURSE / 全部章节</div><nav class="chapter-nav">${data.course.map(c=>`<a href="#/lesson/${c.id}" class="${r.id===c.id&&r.view==='lesson'?'current':''}" ${r.id===c.id&&r.view==='lesson'?'aria-current="page"':''}><span class="chapter-num ${state.completed.includes(c.id)?'done':''}">${state.completed.includes(c.id)?'✓':c.id}</span><span>${escape(c.title.split('：')[0])}</span></a>`).join('')}</nav><div class="sidebar-foot">第一阶段 · 知识与交互学习<br>循序渐进，也可以按需探索。</div></aside><div class="main-shell"><header class="topbar"><button class="menu-toggle" data-action="menu" aria-label="打开课程导航" aria-expanded="false">${icon('menu',21)}</button><span class="breadcrumb">学习实验室 &nbsp; / &nbsp; <b>${({path:'学习路径',lesson:'课程阅读',labs:'交互实验',practice:'GPU 训练',guide:'学习指南',glossary:'术语速查',review:'我的学习'})[r.view]||'学习路径'}</b></span><form id="search-form" class="search-wrap" role="search"><label class="sr-only" for="global-search">搜索课程，按回车</label><input id="global-search" type="search" placeholder="搜索课程…" value="${escape(searchQuery)}" autocomplete="off"><kbd>/</kbd></form></header><main id="main" class="page" tabindex="-1"></main></div>`;
 if(!storageAvailable)$('#main').insertAdjacentHTML('beforeend','<div class="notice">当前浏览器的本地存储不可用。你仍可以学习，请在离开前到“我的学习”导出记录。</div>');
}
function cardsHTML(){
 const query=searchQuery.trim().toLowerCase();const matched=data.course.filter(c=>(activeStage<0||c.stage===activeStage)&&(!query||JSON.stringify(c).toLowerCase().includes(query)));
 return matched.length?matched.map(c=>`<a class="course-card" href="#/lesson/${c.id}"><div class="card-top"><span class="card-index">${c.id} /</span><span class="pill ${c.level==='专题'?'purple':''}">${state.completed.includes(c.id)?'已完成':c.level}</span></div><h3>${escape(c.title)}</h3><p>${escape(c.subtitle)}</p><div class="card-foot"><span>${escape(data.stages[c.stage])} &nbsp; · &nbsp; 约 ${c.minutes} 分钟</span><span class="arrow">↗</span></div></a>`).join(''):`<div class="empty">没有匹配的章节。试试“偏好”“安全”或清除筛选。<br><button data-action="clear-search" style="margin-top:18px">显示全部课程</button></div>`;
}
function pathPage(){
 const current=data.course.find(c=>c.id===state.last)||data.course[0],done=state.completed.length,percent=Math.round(done/data.course.length*100);
 return `<section class="hero"><div><div class="eyebrow">第一阶段 · LLM POST-TRAINING</div><h1>从原理开始，<br>向<span style="color:#7d955f">可靠</span>迈进。</h1><p>把大模型后训练拆成一步步能理解的知识。<br>读懂概念，验证公式，再到 GPU 上训练与评测。</p><div class="button-row"><a class="btn primary" href="#/lesson/${current.id}">${Object.keys(state.answers).length||state.last!=='01'?'继续学习':'开始第一章'} ${icon('arrow',16)}</a><a class="btn ghost" href="#/labs">探索交互实验</a></div></div><div class="journey"><div class="journey-top"><span>YOUR LEARNING JOURNEY</span><span>↗</span></div><div class="journey-number">${current.id}</div><h3>${escape(current.title.split('：')[0])}</h3><p>理解 → 计算 → 验证<br>每一次练习，都让概念更清晰。</p><div class="progress" role="progressbar" aria-label="课程完成进度" aria-valuenow="${percent}" aria-valuemin="0" aria-valuemax="100"><span style="width:${percent}%"></span></div><div class="progress-text"><span>已完成 ${done} / ${data.course.length} 章</span><span>${percent}%</span></div></div></section><div class="stats"><div class="stat"><b>${data.course.length}</b><span>系统学习章节</span></div><div class="stat"><b>${Object.keys(labs).length}</b><span>可操作实验</span></div><div class="stat"><b>${data.course.reduce((s,c)=>s+c.quizzes.length,0)}</b><span>理解检查题</span></div><div class="stat"><b>GPU</b><span>CUDA 训练主线</span></div></div><div class="section-head"><div><h2>你的后训练知识地图</h2><p>从模型基础，到训练方法、安全与评测。</p></div><small>按顺序学习<br>或选择感兴趣的主题</small></div><div class="filters" aria-label="阶段筛选"><button class="filter ${activeStage<0?'selected':''}" data-stage="-1" aria-pressed="${activeStage<0}">全部章节</button>${data.stages.map((s,i)=>`<button class="filter ${activeStage===i?'selected':''}" data-stage="${i}" aria-pressed="${activeStage===i}">${escape(s)}</button>`).join('')}</div>${searchQuery?`<p style="font-size:12px;color:var(--muted)">搜索：${escape(searchQuery)} <button data-action="clear-search" style="padding:4px 8px;margin-left:8px;font-size:10px">清除</button></p>`:''}<div class="cards" id="course-cards">${cardsHTML()}</div><div class="callout">${icon('lab',29)}<div><h3>公式不必只停留在纸上。</h3><p>改变 beta，观察 DPO loss；翻转优势，理解 PPO 裁剪。</p></div><a class="btn" href="#/labs/dpo">打开 DPO 实验 ↗</a></div>${footer()}`;
}
function quizHTML(c){return c.quizzes.map((q,i)=>{const selected=state.answers[c.id]?.[i],answered=Number.isInteger(selected),correct=selected===q.correct;return `<section class="quiz-block"><h3>${i+1}. ${escape(q.question)}</h3><div role="group" aria-label="第 ${i+1} 题选项">${q.options.map((o,j)=>`<button class="quiz-option ${selected===j?(correct?'chosen':'wrong'):''}" data-quiz="${i}" data-option="${j}" data-chapter="${c.id}" aria-pressed="${selected===j}"><span>${String.fromCharCode(65+j)}.</span>${escape(o)}</button>`).join('')}</div>${answered?`<p class="feedback ${correct?'':'incorrect'}" role="status">${correct?'✓ 理解正确。':'再想一步。'} ${escape(q.explanation)}</p>`:''}</section>`;}).join('');}
function completionHTML(c){const passed=c.quizzes.every((q,i)=>state.answers[c.id]?.[i]===q.correct),done=state.completed.includes(c.id);return `<div><b style="font-size:14px">${done?'✓ 本章已完成':passed?'准备好收下这一章了吗？':'读懂，再检验理解'}</b><p>${passed?'你已答对本章全部检查题。可以保存为已完成。':'答对本章全部检查题后，即可标记完成。可以反复尝试。'}</p></div><button class="btn primary" data-complete="${c.id}" ${!passed||done?'disabled':''}>${done?'已记录':'标记本章完成'}</button>`;}
function lessonLabs(c){return (c.practice?`<div class="lab-teaser"><div><h3>把本章接到 token 级训练</h3><p>完成 CUDA 预检，查看报告实际设备、训练日志与逐条生成。</p></div><a class="btn" href="#/practice">进入 GPU 训练 ↗</a></div>`:'')+[c.lab,...(c.extraLabs||[])].filter(Boolean).map(id=>`<div class="lab-teaser"><div><h3>${escape(labs[id].title)}</h3><p>${escape(labs[id].caption)}</p></div><a class="btn" href="#/labs/${id}">动手试一试 ↗</a></div>`).join('');}
function lessonPage(c){
 const index=data.course.indexOf(c),prev=data.course[index-1],next=data.course[index+1];state.last=c.id;save();
 return `<div class="eyebrow">CHAPTER ${c.id} · ${escape(data.stages[c.stage])}</div><h1 class="lesson-title">${escape(c.title)}</h1><p class="lesson-intro">${escape(c.subtitle)}</p><div class="lesson-meta"><span>约 ${c.minutes} 分钟</span><span>${escape(c.level)}</span><span>${c.quizzes.length} 道理解检查</span><button data-bookmark="${c.id}" aria-pressed="${state.bookmarks.includes(c.id)}">${state.bookmarks.includes(c.id)?'★ 已收藏':'☆ 收藏本章'}</button></div><div class="lesson-grid"><article class="lesson-body"><div class="objectives"><h2>学完这一章，你可以</h2><ul>${c.objectives.map(x=>`<li>${escape(x)}</li>`).join('')}</ul></div>${c.sections.map((s,i)=>`<section class="prose-section" id="section-${i}"><h2>${escape(s.title)}</h2>${s.paragraphs.map(p=>`<p>${escape(p)}</p>`).join('')}</section>`).join('')}<aside class="pitfall"><b>注意这个容易混淆的地方</b><p>${escape(c.pitfall)}</p></aside>${lessonLabs(c)}<section class="prose-section" id="quiz"><h2>检查一下自己的理解</h2><p>选择答案后查看解释。答错没有关系，回到概念再试一次。</p><div id="quiz-area">${quizHTML(c)}</div></section><section class="notes prose-section" id="notes"><h2>用自己的话，再讲一遍</h2><label for="lesson-notes" class="sr-only">本章学习笔记</label><textarea id="lesson-notes" data-notes="${c.id}" maxlength="20000" placeholder="一个新理解、一个疑问，或你想复现的实验…">${escape(state.notes[c.id]||'')}</textarea><small id="note-status" role="status">自动保存在此浏览器，可在“我的学习”导出备份。</small></section><section class="prose-section" id="sources"><h2>继续阅读一手资料</h2><ul class="reference-list">${c.references.map(key=>`<li><a href="${escape(data.sources[key][1])}" target="_blank" rel="noopener noreferrer">${escape(data.sources[key][0])} ↗</a></li>`).join('')}</ul></section><div class="complete-box" id="completion">${completionHTML(c)}</div><nav class="pager" aria-label="前后章节">${prev?`<a href="#/lesson/${prev.id}"><small>← 上一章</small>${escape(prev.title)}</a>`:'<span></span>'}${next?`<a href="#/lesson/${next.id}" style="text-align:right"><small>下一章 →</small>${escape(next.title)}</a>`:'<a href="#/review">查看我的学习 →</a>'}</nav></article><aside class="lesson-aside"><h3>本章导航</h3><nav class="toc">${c.sections.map((s,i)=>`<a href="#section-${i}" data-scroll="section-${i}">${escape(s.title)}</a>`).join('')}<a href="#quiz" data-scroll="quiz">检查理解</a><a href="#notes" data-scroll="notes">学习笔记</a><a href="#sources" data-scroll="sources">一手资料</a></nav><div class="aside-box">前置知识${c.prerequisites.length?c.prerequisites.map(id=>`<a href="#/lesson/${id}">${id} · ${escape(data.course.find(x=>x.id===id).title.split('：')[0])}</a>`).join(''):'<p>从这里开始，不需要先学其他章节。</p>'}</div><div class="aside-box">教学计算用于理解原理。本站不在浏览器内训练真实语言模型。</div></aside></div>${footer()}`;
}
const range=(id,label,value,min,max,step=0.1)=>`<label class="field" for="${id}"><span>${label}<output for="${id}" id="${id}-value">${value}</output></span><input id="${id}" name="${id}" type="range" value="${value}" min="${min}" max="${max}" step="${step}"></label>`;
const number=(id,label,value,min,max,step=1)=>`<label class="field"><span>${label}</span><input id="${id}" name="${id}" type="number" value="${value}" min="${min}" ${max!==undefined?`max="${max}"`:''} step="${step}" required></label>`;
function labControls(id){switch(id){
 case'gradient':return number('theta','当前参数 θ',0,-1000,1000,.00000001)+`<label class="field" for="target"><span id="target-label">示范目标 y</span><select id="target" name="target" aria-labelledby="target-label"><option value="1">动作 1 是正确示范</option><option value="0">动作 0 是正确示范</option></select></label>`+range('eta','学习率 η',.2,0,2,.05)+`<button type="button" class="btn primary" data-action="gradient-step">执行当前这一步更新 →</button>`;
 case'gae':return [0,0,1].map((x,i)=>number('r'+i,'步骤 '+i+' 的奖励 r',x,-100,100,.01)).join('')+[.2,.3,.4].map((x,i)=>number('v'+i,'步骤 '+i+' 的价值 V',x,-100,100,.01)).join('')+number('bootstrap','片段后状态的价值 V₃',.5,-100,100,.01)+range('gamma','折扣因子 γ',.9,0,1,.05)+range('lambda','GAE 参数 λ',.95,0,1,.05)+`<label class="field" for="ending"><span id="ending-label">第三步之后发生了什么？</span><select id="ending" name="ending" aria-labelledby="ending-label"><option value="terminal">环境真正终止（忽略 V₃）</option><option value="truncated">只截断采样（使用 V₃）</option></select></label>`;
 case'temperature':return range('temperature','温度 T',1,.1,3,.1);
 case'sft':return `<p class="lab-note" style="margin-top:0">教学序列：用户 / 问题 / 助手 / 回答。勾选计入 loss 的 token。</p><div class="token-masks">${['用户①','用户②','助手①','助手②'].map((s,i)=>`<label><input type="checkbox" name="mask" value="${i}" ${i>1?'checked':''}> ${s}</label>`).join('')}</div>${[.8,.6,.5,.25].map((p,i)=>range('p'+i,['用户①概率','用户②概率','助手①概率','助手②概率'][i],p,.01,1,.01)).join('')}`;
 case'lora':return number('din','输入维度 d_in',4096,1,65536)+number('dout','输出维度 d_out',4096,1,65536)+range('rank','秩 r',8,1,256,1);
 case'reward':return range('rw','chosen 奖励',2,-8,8,.1)+range('rl','rejected 奖励',0,-8,8,.1);
 case'dpo':return number('pw','策略 chosen log-prob',-2,-1000,0,.1)+number('pl','策略 rejected log-prob',-4,-1000,0,.1)+number('refw','参考 chosen log-prob',-3,-1000,0,.1)+number('refl','参考 rejected log-prob',-4,-1000,0,.1)+range('beta','β',.1,.01,2,.01);
 case'ppo':return range('ratio','当前 / 旧策略概率比',1.5,0,2,.01)+range('advantage','优势 A',1,-2,2,.1)+range('epsilon','裁剪范围 ε',.2,0,.8,.05);
 case'grpo':return `<label class="field"><span>同一问题的奖励，逗号分隔</span><input id="rewards" name="rewards" value="0, 0, 1, 1" autocomplete="off"></label><div class="button-row"><button type="button" data-rewards="0,0,1,1">有成功也有失败</button><button type="button" data-rewards="1,1,1,1">全部同分</button></div>`;
 case'sampling':return range('prob','单次成功率 p',.3,0,1,.01)+range('attempts','尝试次数 N',4,1,32,1);
 case'safety':return number('harmtotal','有害请求总数',100,0,100000)+number('harmful','其中产生有害回答',15,0,100000)+number('benigntotal','合法请求总数',100,0,100000)+number('refused','其中被误拒绝',8,0,100000)+`<button type="button" data-action="refuse-all">模拟：全部拒绝</button>`;
 case'memory':return range('billions','参数量（十亿 / B）',7,.5,70,.5)+range('workers','理想分片卡数',1,1,16,1)+range('activation','每卡激活估计（GB）',4,0,32,.5);
}}
function labPage(id){
 if(!id)return `<div class="eyebrow">LEARN BY CHANGING</div><h1 class="lesson-title">让公式动起来。</h1><p class="lesson-intro">调一个参数，先预测，再观察。每个数字都能回到公式。</p><div class="notice">这些实验在浏览器本地计算，不调用模型、不使用 GPU。数值用于教学，不能作为真实训练或 benchmark 结果。</div><div class="button-row" style="margin-bottom:24px"><a class="btn primary" href="./downloads/safeposttrain-teaching-labs.zip" download>完整实验包 ZIP ↓</a><a class="btn" href="./downloads/core_math.py" download>下载数值实验 .py ↓</a><a class="btn" href="./downloads/toy_training.py" download>下载策略训练示例 .py ↓</a><a class="btn ghost" href="./downloads/README.md" download>实验运行指南 ↓</a></div><div class="cards">${Object.entries(labs).map(([key,l],i)=>`<a class="course-card" href="#/labs/${key}"><div class="card-top"><span class="card-index">EXP ${String(i+1).padStart(2,'0')}</span><span class="pill purple">交互实验</span></div><h3>${l.title}</h3><p>${l.caption}</p><div class="card-foot"><span>关联第 ${l.chapter} 章</span><span class="arrow">↗</span></div></a>`).join('')}</div>${footer()}`;
 const l=labs[id];if(!l)return notFound();
 return `<div class="eyebrow">INTERACTIVE LAB · ${l.chapter}</div><h1 class="lesson-title">${l.title}</h1><p class="lesson-intro">${l.caption}</p><div class="button-row" style="margin-bottom:25px"><a class="btn ghost" href="#/lesson/${l.chapter}">← 回到相关课程</a><a class="btn ghost" href="#/labs">全部实验</a></div><div class="lab-layout"><section class="lab-controls"><h2>01 / 改变输入</h2><form id="lab-form" data-lab="${id}">${labControls(id)}</form><button data-action="reset-lab" class="btn ghost">恢复默认参数</button><p class="lab-note">${l.note}</p></section><section class="lab-output"><h2>02 / 观察结果</h2><div class="formula">${l.formula}</div><div id="lab-result" aria-live="polite"></div></section></div>${footer()}`;
}
const fmt=(n,d=4)=>n===null?'无定义':Number.isFinite(n)?n.toFixed(d):'无定义';
const metric=(value,label)=>`<div><div class="metric-number">${value}</div><div class="metric-label">${label}</div></div>`;
function plot(points,label){const w=360,h=160,pad=24,ys=points.flatMap(p=>[p[1],p[2]]),min=Math.min(0,...ys),max=Math.max(1,...ys),scale=max-min||1;const path=i=>points.map((p,j)=>`${j?'L':'M'}${pad+p[0]*(w-2*pad)/2},${h-pad-(p[i]-min)/scale*(h-2*pad)}`).join(' ');return `<svg class="plot" viewBox="0 0 ${w} ${h}" role="img" aria-label="${escape(label)}"><line x1="${pad}" y1="${h-pad}" x2="${w-pad}" y2="${h-pad}" stroke="#ccd5c5"/><line x1="${pad}" y1="${pad}" x2="${pad}" y2="${h-pad}" stroke="#ccd5c5"/><path d="${path(1)}" fill="none" stroke="#a18aba" stroke-width="2" stroke-dasharray="4 3"/><path d="${path(2)}" fill="none" stroke="#315f43" stroke-width="3"/><text x="${pad}" y="${h-5}" fill="#84917f" font-size="9">0</text><text x="${w-pad}" y="${h-5}" fill="#84917f" font-size="9">2</text><text x="145" y="${h-5}" fill="#84917f" font-size="9">概率比 ratio</text></svg>`;}
function updateLab(){
 const form=$('#lab-form');if(!form)return;const id=form.dataset.lab;
 const val=name=>{const input=form.elements.namedItem(name);if(input.value.trim()===''||!input.checkValidity())throw Error('请按输入框的范围填写有效数值。');const n=Number(input.value);if(!Number.isFinite(n))throw Error('请输入有效数字。');return n;};
 form.querySelectorAll('input[type=range]').forEach(x=>{const out=$('#'+x.id+'-value');if(out)out.textContent=x.value;});
 let html='';try{switch(id){
  case'gradient':{const r=math.sftStep(val('theta'),val('target'),val('eta'));html=metric(fmt(r.probability*100,3)+'%','当前动作 1 概率')+`<table class="table"><tr><th>当前 loss</th><td>${fmt(r.loss,6)}</td></tr><tr><th>梯度 p − y</th><td>${fmt(r.gradient,6)}</td></tr><tr><th>更新后的 θ</th><td>${fmt(r.nextTheta,6)}</td></tr><tr><th>更新后动作 1 概率</th><td>${fmt(r.nextProbability*100,3)}%</td></tr><tr><th>更新后 loss</th><td>${fmt(r.nextLoss,6)}</td></tr></table><p class="lab-note">右侧先预览这一步的结果。点击“执行当前这一步更新”，左侧参数才会变化。切换 y，观察梯度方向翻转；η=0 时权重不变。</p>`;break;}
  case'gae':{const rewards=[0,1,2].map(i=>val('r'+i)),values=[0,1,2].map(i=>val('v'+i));values.push(val('bootstrap'));const r=math.gaeTrace(rewards,values,val('gamma'),val('lambda'),form.elements.ending.value==='terminal');html=metric(fmt(r.advantages[0],6),'第一步的 GAE 优势 A₀')+`<div class="table-scroll" role="region" aria-label="逐步 GAE 计算表" tabindex="0"><table class="table"><thead><tr><th>步 t</th><th>r</th><th>V</th><th>δ</th><th>A</th><th>A+V</th></tr></thead><tbody>${rewards.map((x,i)=>`<tr><td>${i}</td><td>${fmt(x,2)}</td><td>${fmt(values[i],2)}</td><td>${fmt(r.deltas[i],3)}</td><td>${fmt(r.advantages[i],6)}</td><td>${fmt(r.returns[i],6)}</td></tr>`).join('')}</tbody></table></div><p class="lab-note">从最后一行向上计算：先算 TD 残差 δ，再加上 γλ 倍的下一步优势。λ=0 时只用本步残差，λ=1 时得到这段轨迹的多步回报减去价值估计。</p><p class="lab-note">当前末端处理：${form.elements.ending.value==='terminal'?'环境已终止，V₃ 不进入计算。':'轨迹被截断，V₃ 进入最后一步的 bootstrap。'}</p>`;break;}
  case'temperature':{const r=math.distribution([2,1,0,-1],val('temperature'));html=metric(fmt(r.entropy),'分布熵（nats）')+r.p.map((p,i)=>`<div class="bar-row"><span>候选 ${i+1}</span><div class="bar-track"><div class="bar-fill" style="width:${p*100}%"></div></div><span>${fmt(p*100,1)}%</span></div>`).join('')+'<p class="lab-note">四个候选的概率总和为 1。分布更平，不意味着答案更正确。</p>';break;}
  case'sft':{const p=[0,1,2,3].map(i=>val('p'+i)),mask=[...form.querySelectorAll('[name=mask]')].map(x=>+x.checked),r=math.sftLoss(p,mask);html=metric(r.loss===null?'无定义':fmt(r.loss),'有效 token 平均负对数似然')+`<p class="lab-note">有效监督 token：${r.count} / 4</p><table class="table"><thead><tr><th>位置</th><th>mask</th><th>−mask · ln p</th></tr></thead><tbody>${r.terms.map((x,i)=>`<tr><td>${i+1}</td><td>${mask[i]}</td><td>${fmt(x)}</td></tr>`).join('')}</tbody></table>${r.count?'':'<p class="lab-error">没有有效监督 token，不能把空平均当成零 loss。</p>'}`;break;}
  case'lora':{const r=math.loraCount(val('din'),val('dout'),val('rank'));html=metric(r.adapter.toLocaleString(),'LoRA 可训练参数')+`<table class="table"><tr><th>原层权重参数</th><td>${r.base.toLocaleString()}</td></tr><tr><th>适配器 / 原层比例</th><td>${fmt(r.percent,3)}%</td></tr></table><p class="lab-note">这表示新增可训练参数相对原层权重的比例。激活与其他训练状态未计入。</p>`;break;}
  case'reward':{const r=math.rewardPair(val('rw'),val('rl'));html=metric(fmt(r.probability*100,2)+'%','chosen 胜出的模型概率')+`<table class="table"><tr><th>奖励分差</th><td>${fmt(r.margin,2)}</td></tr><tr><th>偏好 loss</th><td>${fmt(r.loss)}</td></tr></table>`;break;}
  case'dpo':{const r=math.dpoLoss(val('pw'),val('pl'),val('refw'),val('refl'),val('beta'));html=metric(fmt(r.loss),'DPO 单样本 loss')+`<table class="table"><tr><th>相对参考 margin</th><td>${fmt(r.margin)}</td></tr><tr><th>z = β × margin</th><td>${fmt(r.z)}</td></tr><tr><th>σ(z)</th><td>${fmt(r.probability)}</td></tr></table><p class="lab-note">margin 为零时，loss = ln 2 ≈ 0.6931。正 margin 表示相对参考模型更支持 chosen。</p>`;break;}
  case'ppo':{const a=val('advantage'),eps=val('epsilon'),r=math.ppoSurrogate(val('ratio'),a,eps);html=metric(fmt(r.surrogate),'裁剪后的 surrogate（最大化）')+`<table class="table"><tr><th>未裁剪 ratio × A</th><td>${fmt(r.raw)}</td></tr><tr><th>裁剪分支</th><td>${fmt(r.clipped)}</td></tr><tr><th>最小化的 policy loss</th><td>${fmt(r.loss)}</td></tr></table>`+plot(Array.from({length:61},(_,i)=>{const ratio=i/30,r=math.ppoSurrogate(ratio,a,eps);return[ratio,r.raw,r.surrogate];}),'PPO 目标随概率比变化；当前优势 '+a)+`<div class="legend"><span>裁剪目标</span><span>未裁剪目标</span></div>`;break;}
  case'grpo':{const parts=form.elements.rewards.value.split(/[,，\s]+/).filter(Boolean);if(!parts.length)throw Error('请输入至少两个奖励。');const rewards=parts.map(Number),r=math.groupAdvantages(rewards);html=`<div class="metric-row">${metric(fmt(r.mean,3),'组均值')}${metric(fmt(r.std,3),'总体标准差')}</div><table class="table"><thead><tr><th>回答</th><th>奖励</th><th>优势</th></tr></thead><tbody>${rewards.map((x,i)=>`<tr><td>${i+1}</td><td>${escape(x)}</td><td>${fmt(r.advantages[i])}</td></tr>`).join('')}</tbody></table>${r.std===0?'<p class="notice">全组同分：组内优势均为零。此反馈没有提供区分信号。</p>':''}`;break;}
  case'sampling':{const p=val('prob'),n=val('attempts'),r=math.samplingProbability(p,n);html=metric(fmt(r*100,2)+'%','理想条件下至少一次成功')+`<div class="bar-row"><span>单次</span><div class="bar-track"><div class="bar-fill" style="width:${p*100}%"></div></div><span>${fmt(p*100,0)}%</span></div><div class="bar-row"><span>${n} 次</span><div class="bar-track"><div class="bar-fill" style="width:${r*100}%"></div></div><span>${fmt(r*100,0)}%</span></div><p class="lab-note">计算量约随候选数增加。这里没有计算不完美评分器错选答案的影响。</p>`;break;}
  case'safety':{const r=math.safetyMetrics(val('harmtotal'),val('harmful'),val('benigntotal'),val('refused'));html=metric(r.harmRate===null?'无定义':fmt(r.harmRate*100,1)+'%','有害完成率 · 越低越好')+metric(r.refusalRate===null?'无定义':fmt(r.refusalRate*100,1)+'%','合法请求误拒绝率 · 越低越好')+`<p class="lab-note">${r.refusalRate===1?'全部合法请求被拒绝：即使有害完成为零，也不能说明系统可用。':'两个分母分别来自有害与合法请求。样本总数为零时，该比率无定义。'}</p>`;break;}
  case'memory':{const r=math.memoryEstimate(val('billions'),val('workers'),val('activation'));html=metric(fmt(r.perWorker,1)+' GB','理想分片后每卡状态 + 输入的激活估计')+`<table class="table"><thead><tr><th>全模型静态状态</th><th>GB</th></tr></thead><tbody><tr><td>权重 · 2 B/参数</td><td>${fmt(r.weights,1)}</td></tr><tr><td>梯度 · 2 B/参数</td><td>${fmt(r.gradients,1)}</td></tr><tr><td>主副本 · 4 B/参数</td><td>${fmt(r.master,1)}</td></tr><tr><td>Adam 状态 · 8 B/参数</td><td>${fmt(r.optimizer,1)}</td></tr></tbody></table><p class="lab-note">实际峰值还包含未估算的通信、临时张量、框架和采样开销。</p>`;break;}
 }}catch(error){html=`<div class="lab-error" role="alert">${escape(error.message)}</div>`;}$('#lab-result').innerHTML=html;
}
function glossaryPage(){return `<div class="eyebrow">A SMALL DICTIONARY</div><h1 class="lesson-title">遇到术语，随时查。</h1><p class="lesson-intro">用一句话找回直觉，再回到相应章节深入理解。</p><label class="sr-only" for="term-search">搜索中英文术语</label><input id="term-search" type="search" placeholder="搜索中英文术语，例如 advantage、优势…" style="width:100%;margin-bottom:25px"><div class="glossary-grid" id="terms">${termsHTML('')}</div>${footer()}`;}
function termsHTML(q){const terms=data.glossary.filter(t=>(t.term+' '+t.definition).toLowerCase().includes(q.toLowerCase()));return terms.length?terms.map(t=>`<article class="term"><h3>${escape(t.term)}</h3><p>${escape(t.definition)}</p><a href="#/lesson/${t.chapter}">在第 ${t.chapter} 章理解它 ↗</a></article>`).join(''):'<div class="empty">没有找到这个术语，试试另一种中英文写法。</div>';}
function reviewPage(){const bookmarked=data.course.filter(c=>state.bookmarks.includes(c.id)),notes=data.course.filter(c=>state.notes[c.id]?.trim()),mistakes=data.course.filter(c=>state.mistakes[c.id]?.length);return `<div class="eyebrow">YOUR LEARNING SPACE</div><h1 class="lesson-title">把理解，慢慢留下来。</h1><p class="lesson-intro">已完成 ${state.completed.length} / ${data.course.length} 章。笔记、收藏和答题记录仅保存在当前浏览器。</p><div class="button-row" style="margin-bottom:25px"><button class="btn primary" data-action="export">导出学习记录 ↓</button><label class="btn import-label" for="import-progress">导入学习记录 ↑</label><input type="file" id="import-progress" accept="application/json,.json" class="sr-only"></div><div class="notice">更换设备或清除浏览器数据前，请先导出。导入会合并笔记、收藏和完成记录；同章笔记冲突时保留两份内容。</div><div class="section-head"><h2>收藏的章节</h2><small>${bookmarked.length} 章</small></div>${bookmarked.length?`<div class="cards">${bookmarked.map(c=>`<a class="course-card" href="#/lesson/${c.id}"><div class="card-top"><span class="card-index">${c.id}</span><span class="pill">已收藏</span></div><h3>${escape(c.title)}</h3><p>${escape(c.subtitle)}</p></a>`).join('')}</div>`:'<div class="empty">阅读时点击“收藏本章”，把想重访的知识留在这里。</div>'}<div class="section-head" style="margin-top:32px"><h2>值得再想一次</h2><small>保留曾答错的题</small></div>${mistakes.length?mistakes.map(c=>`<div class="review-row"><h3><a href="#/lesson/${c.id}">${c.id} · ${escape(c.title)} ↗</a></h3>${state.mistakes[c.id].map(i=>`<p>${escape(c.quizzes[i].question)}<br><small>${state.answers[c.id]?.[i]===c.quizzes[i].correct?'✓ 已纠正，仍可复习':'待重新理解'}</small></p>`).join('')}</div>`).join(''):'<div class="empty">目前没有错题记录。完成课程中的理解检查，这里会保留需要复习的概念。</div>'}<div class="section-head" style="margin-top:32px"><h2>我的笔记</h2><small>${notes.length} 篇</small></div>${notes.length?notes.map(c=>`<article class="review-row"><h3><a href="#/lesson/${c.id}">${c.id} · ${escape(c.title)} ↗</a></h3><p>${escape(state.notes[c.id])}</p></article>`).join(''):'<div class="empty">每章末尾都有笔记区。试着用自己的话解释一个概念。</div>'}${footer()}`;}
function notFound(){return `<div class="empty"><h1>这页课程不存在</h1><p>可以从学习路径重新选择。</p><a class="btn primary" href="#/path">返回学习路径</a></div>`;}
function render(scroll=true){const r=route(),oldY=window.scrollY;shell();let content;switch(r.view){case'path':content=pathPage();break;case'lesson':{const c=data.course.find(c=>c.id===r.id);content=c?lessonPage(c):notFound();break;}case'labs':content=labPage(r.id);break;case'practice':content=practicePage()+footer();break;case'guide':content=guidePage(r.id||'study')+footer();break;case'glossary':content=glossaryPage();break;case'review':content=reviewPage();break;default:content=notFound();}$('#main').insertAdjacentHTML('beforeend',content);updateLab();if(r.view==='practice')mountPractice();if(r.view==='guide')mountGuide();document.title=(r.view==='lesson'?data.course.find(c=>c.id===r.id)?.title:r.view==='labs'&&r.id?labs[r.id]?.title:r.view==='practice'?'GPU 训练实战':r.view==='guide'?'学习指南':'后训练学习实验室')+' · SafePostTrain Lab';if(scroll)window.scrollTo(0,0);else window.scrollTo(0,oldY);}
document.addEventListener('click',e=>{
 const a=e.target.closest('[data-action]'),stage=e.target.closest('[data-stage]'),q=e.target.closest('[data-quiz]'),complete=e.target.closest('[data-complete]'),bookmark=e.target.closest('[data-bookmark]'),scroll=e.target.closest('[data-scroll]'),preset=e.target.closest('[data-rewards]');
 if(scroll){e.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:'smooth'});return;}
 if(stage){activeStage=Number(stage.dataset.stage);render(false);return;}
 if(q){const c=data.course.find(c=>c.id===q.dataset.chapter),i=Number(q.dataset.quiz),option=Number(q.dataset.option);state.answers[c.id]??=Array(c.quizzes.length).fill(null);state.answers[c.id][i]=option;if(option!==c.quizzes[i].correct){state.mistakes[c.id]=[...new Set([...(state.mistakes[c.id]||[]),i])];state.completed=state.completed.filter(id=>id!==c.id);}save();$('#quiz-area').innerHTML=quizHTML(c);$('#completion').innerHTML=completionHTML(c);document.querySelector(`[data-quiz="${i}"][data-option="${option}"]`).focus({preventScroll:true});return;}
 if(complete){const c=data.course.find(c=>c.id===complete.dataset.complete);if(c.quizzes.every((q,i)=>state.answers[c.id]?.[i]===q.correct)){state.completed=[...new Set([...state.completed,c.id])];save();render(false);toast('本章已完成，学习进度已保存。');}return;}
 if(bookmark){const id=bookmark.dataset.bookmark;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();bookmark.textContent=state.bookmarks.includes(id)?'★ 已收藏':'☆ 收藏本章';bookmark.setAttribute('aria-pressed',String(state.bookmarks.includes(id)));return;}
 if(preset){$('#rewards').value=preset.dataset.rewards;updateLab();return;}
 if(a){switch(a.dataset.action){case'menu':{const open=$('.sidebar').classList.toggle('open');a.setAttribute('aria-expanded',String(open));a.setAttribute('aria-label',open?'关闭课程导航':'打开课程导航');break;}case'close-menu':$('.sidebar').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle').setAttribute('aria-label','打开课程导航');break;case'clear-search':searchQuery='';activeStage=-1;render(false);break;case'gradient-step':{const form=$('#lab-form');if(!form.checkValidity()){toast('请先填写有效参数。');break;}const r=math.sftStep(Number($('#theta').value),Number($('#target').value),Number($('#eta').value));$('#theta').value=r.nextTheta.toFixed(8);updateLab();break;}case'reset-lab':$('#lab-form').innerHTML=labControls($('#lab-form').dataset.lab);updateLab();break;case'refuse-all':$('#harmful').value=0;$('#refused').value=$('#benigntotal').value;updateLab();break;case'export':{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='safeposttrain-learning.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('学习记录已导出。');break;}}}
 if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();$('#main').scrollIntoView();}
});
document.addEventListener('input',e=>{if(e.target.closest('#lab-form'))updateLab();if(e.target.id==='term-search')$('#terms').innerHTML=termsHTML(e.target.value);if(e.target.dataset.notes){state.notes[e.target.dataset.notes]=e.target.value;save();$('#note-status').textContent=storageAvailable?'已自动保存到当前浏览器。':'未能持久保存，请到“我的学习”导出备份。';}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='search-form'){searchQuery=$('#global-search').value;activeStage=-1;if(route().view==='path')render();else location.hash='#/path';}});
document.addEventListener('change',async e=>{if(e.target.id!=='import-progress')return;const file=e.target.files?.[0];if(!file)return;const snapshot=JSON.stringify(state);try{if(file.size>2_000_000)throw Error('记录文件过大，请使用 2MB 以内的导出文件。');const incoming=validateState(JSON.parse(await file.text()));for(const c of data.course){const id=c.id;if(incoming.notes[id])state.notes[id]=mergeNotes(state.notes[id],incoming.notes[id]);if(incoming.answers[id]&&(!state.completed.includes(id)||incoming.completed.includes(id)))state.answers[id]=incoming.answers[id];state.mistakes[id]=[...new Set([...(state.mistakes[id]||[]),...(incoming.mistakes[id]||[])])];}state.completed=[...new Set([...state.completed,...incoming.completed])];state.bookmarks=[...new Set([...state.bookmarks,...incoming.bookmarks])];state=validateState(state);save();render(false);toast('学习记录已合并。');}catch(error){state=JSON.parse(snapshot);toast('无法导入：'+(error instanceof SyntaxError?'文件格式不正确，请使用本站导出的 JSON 学习记录。':error.message));} });
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#global-search').focus();}if(e.key==='Escape'){$('.sidebar')?.classList.remove('open');const b=$('.menu-toggle');if(b){b.setAttribute('aria-expanded','false');b.setAttribute('aria-label','打开课程导航');}}});
window.addEventListener('hashchange',()=>render());
try{const response=await fetch('./content/course.json');if(!response.ok)throw Error('课程资源加载失败');data=await response.json();try{const raw=localStorage.getItem(KEY);if(raw)state=validateState(JSON.parse(raw));}catch{storageAvailable=false;}render();}catch(error){$('#app').innerHTML=`<div class="loading"><h1>暂时无法打开课程</h1><p>${escape(error.message)}</p><p>请通过 HTTP 服务打开本站，而不是直接双击 HTML 文件。</p><button onclick="location.reload()">重新加载</button></div>`;}
